import{_ as l}from"./chunks/Audio.COine8Wh.js";import{_ as i}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as s,j as t,G as a,ae as r,a as o}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Halt All Lethal Trafficking of Fentanyl Act","description":"","frontmatter":{"legisId":"2025-07-16-halt-all-lethal-trafficking-of-fentanyl-act","title":"Halt All Lethal Trafficking of Fentanyl Act","displayTitle":"Halt All Lethal Trafficking of Fentanyl Act","lawNumber":"119-26","billNumber":"S. 331","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ26.xml","publishDate":"2025-07-16T00:00:00-05:00","industries":["law-enforcement","healthcare"],"agencies":["Department of Justice"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Halt All Lethal Trafficking of Fentanyl Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-16-halt-all-lethal-trafficking-of-fentanyl-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Halt All Lethal Trafficking of Fentanyl Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-16-halt-all-lethal-trafficking-of-fentanyl-act\\",\\"datePublished\\":\\"2025-07-16T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-16-halt-all-lethal-trafficking-of-fentanyl-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-07-16-halt-all-lethal-trafficking-of-fentanyl-act.md","filePath":"congress-bills/2025-07-16-halt-all-lethal-trafficking-of-fentanyl-act.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2025-07-16-halt-all-lethal-trafficking-of-fentanyl-act.md"},m=Object.assign(c,{setup(f){return(d,e)=>(s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"halt-all-lethal-trafficking-of-fentanyl-act",tabindex:"-1"},[o("Halt All Lethal Trafficking of Fentanyl Act "),t("a",{class:"header-anchor",href:"#halt-all-lethal-trafficking-of-fentanyl-act","aria-label":'Permalink to "Halt All Lethal Trafficking of Fentanyl Act"'},"​")],-1)),a(l),a(i,{list:"/congress-bills"}),e[1]||(e[1]=r('<p>Signed into law on Wednesday, July 16, 2025. Public Law 119-26, S. 331.</p><p><strong>Headline:</strong> The HALT Fentanyl Act permanently classifies fentanyl-related substances as Schedule I while easing requirements for qualifying research.</p><p><strong>Why it matters:</strong> The law applies federal fentanyl trafficking penalties to a broad class of substances and streamlines how approved researchers may study them.</p><p><strong>What the law does:</strong></p><ul><li>Places fentanyl-related substances meeting specified structural criteria in Schedule I unless exempted or separately scheduled.</li><li>Applies existing federal fentanyl penalties to trafficking, importing, and exporting covered substances.</li><li>Allows the Attorney General to publish a non-exhaustive list of covered substances.</li><li>Expedites registration for certain federally supported or authorized Schedule I research, including a 30-day notice process and a 45-day decision deadline.</li><li>Lets qualifying institutions use one registration for certain researchers and nearby sites, continue some newly restricted research, and manufacture small quantities for research.</li><li>Requires the Attorney General to issue implementing rules within six months, with the law’s changes effective upon enactment.</li></ul><p><strong>Who it affects:</strong></p><ul><li>People who traffic, import, or export covered fentanyl-related substances.</li><li>Researchers and institutions conducting federally supported or authorized Schedule I research.</li><li>Federal drug-control and law-enforcement officials implementing the classification and registration rules.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Covered fentanyl-related substances are subject to Schedule I controls and federal fentanyl trafficking penalties.</li><li>Qualifying medical and scientific research may proceed under faster and more flexible registration procedures.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="halt-all-lethal-trafficking-of-fentanyl-act-1" tabindex="-1">Halt All Lethal Trafficking of Fentanyl Act <a class="header-anchor" href="#halt-all-lethal-trafficking-of-fentanyl-act-1" aria-label="Permalink to &quot;Halt All Lethal Trafficking of Fentanyl Act&quot;">​</a></h3><p>The HALT Fentanyl Act permanently places a broadly defined class of fentanyl-related substances in Schedule I unless a substance is exempted or placed in another schedule. It applies federal fentanyl trafficking penalties to those substances while simplifying registration and related requirements for certain Schedule I research.</p><p><strong>Key takeaways:</strong></p><ul><li>Fentanyl-related substances meeting specified structural criteria are classified as Schedule I unless they are exempted or separately placed in another schedule.</li><li>The Attorney General may publish a list of covered fentanyl-related substances, but a substance can be controlled even if it does not appear on that list.</li><li>Existing federal fentanyl penalties apply to trafficking, importing, and exporting covered fentanyl-related substances.</li><li>Certain federally supported or federally authorized Schedule I research qualifies for expedited registration procedures, including a 30-day notice process for already registered researchers and a 45-day decision deadline for other applicants.</li><li>The Act allows qualifying institutions to use one registration for certain researchers and nearby research sites, continue some research when a substance is newly placed in Schedule I, and conduct small-scale manufacturing needed for research.</li><li>The Attorney General must issue implementing rules within six months, while the Act’s changes apply from its enactment date.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ26.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ26.xml</a></p>',15))]))}});export{g as __pageData,m as default};
